import{_ as a,o as n,c as r,a5 as d,j as o,a as t,t as c}from"./chunks/framework.BfQ7H7Qx.js";const v=JSON.parse('{"title":"Technical Implementation Plan — FR 3.6.9: Approval Sequence & Multi-Role Task Status Governance (v4.0)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/plan.md","filePath":"feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/plan.md"}'),i={name:"feature/srs/05-content-task-workflow/3-6-9-approval-sequence-creator-manager-client/plan.md"};function s(l,e,h,u,p,g){return n(),r("div",null,[e[12]||(e[12]=d('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a> · <a href="./../../../../ba/13-task-status-and-approval-governance.html">BA Governance →</a></p><h1 id="technical-implementation-plan-—-fr-3-6-9-approval-sequence-multi-role-task-status-governance-v4-0" tabindex="-1">Technical Implementation Plan — FR 3.6.9: Approval Sequence &amp; Multi-Role Task Status Governance (v4.0) <a class="header-anchor" href="#technical-implementation-plan-—-fr-3-6-9-approval-sequence-multi-role-task-status-governance-v4-0" aria-label="Permalink to &quot;Technical Implementation Plan — FR 3.6.9: Approval Sequence &amp; Multi-Role Task Status Governance (v4.0)&quot;">​</a></h1><p>&gt; Triển khai kỹ thuật dựa trên <a href="./spec.html">spec.md (v4.0)</a> và <a href="./../../../../ba/13-task-status-and-approval-governance.html">BA 13 — Quản trị Trạng thái &amp; Phê duyệt Đa tầng</a>.</p><hr><h2 id="_1-thanh-phan-he-thong-danh-muc-file-cham-toi" tabindex="-1">1. Thành phần Hệ thống &amp; Danh mục File Chạm tới <a class="header-anchor" href="#_1-thanh-phan-he-thong-danh-muc-file-cham-toi" aria-label="Permalink to &quot;1. Thành phần Hệ thống &amp; Danh mục File Chạm tới&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Tầng / Repository</th><th style="text-align:left;">File &amp; Class Chạm tới</th><th style="text-align:left;">Trách nhiệm Thay đổi Kỹ thuật</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Backend — Task Status &amp; Creation (<code>brandhub-business-service</code>)</strong></td><td style="text-align:left;"><code>service/impl/task/TaskServiceImpl.java</code>&lt;br/&gt;<code>exception/ErrorCode.java</code></td><td style="text-align:left;">1. Khóa <code>updateStatus()</code>: chặn <code>IN_REVIEW</code> và <code>FINISHED</code> (<code>409 TASK_WORKFLOW_REQUIRED</code>) đối với mọi Task thuộc quy trình duyệt; chặn <code>Creator</code> chuyển sang <code>CANCELLED</code> (<code>403 FORBIDDEN</code>), khi <code>Owner</code>/<code>Manager</code> hủy thì ghi <code>Cancellation</code>, dọn <code>reviewStep</code> và hủy lịch đăng.&lt;br/&gt;2. Sửa <code>createTask()</code> &amp; <code>createStandaloneTask()</code>: khi người tạo là <code>Creator</code> và không truyền <code>supervisorId</code> hợp lệ khác <code>assigneeId</code>, gán <code>supervisorId = defaultManager</code> thay vì <code>currentUser.getId()</code>.</td></tr><tr><td style="text-align:left;"><strong>Backend — Workflow &amp; Platform Policy (<code>brandhub-business-service</code>)</strong></td><td style="text-align:left;"><code>service/impl/task/TaskWorkflowService.java</code>&lt;br/&gt;<code>service/impl/task/TaskPlatformPolicy.java</code>&lt;br/&gt;<code>service/impl/media/CampaignSubtaskService.java</code></td><td style="text-align:left;">1. Bổ sung <code>MemberRole.OWNER</code> vào <code>TaskWorkflowService.start()</code>, <code>TaskPlatformPolicy.requireManager()</code>, và <code>CampaignSubtaskService.canManage()</code> / <code>allowed()</code> trên task mạng xã hội độc lập.&lt;br/&gt;2. Chặn gán <code>supervisorId == assigneeId</code> khi <code>assignee</code> là <code>Creator</code> trong <code>TaskWorkflowService.field()</code> &amp; <code>assign()</code>.&lt;br/&gt;3. Giới hạn <code>TaskWorkflowService.partners()</code> chỉ cho <code>Owner</code>, <code>Manager</code> và người tham gia trực tiếp vào Task (<code>participant</code>).&lt;br/&gt;4. Sửa <code>CampaignSubtaskService.supervisor()</code> kế thừa <code>task.getSupervisorId()</code> trước khi fallback.</td></tr><tr><td style="text-align:left;"><strong>Backend — Section &amp; Auto-Settlement (<code>brandhub-business-service</code>)</strong></td><td style="text-align:left;"><code>service/impl/workspace/SectionPolicy.java</code>&lt;br/&gt;<code>service/impl/workspace/SectionService.java</code>&lt;br/&gt;<code>service/impl/workspace/SectionNotifier.java</code></td><td style="text-align:left;">1. Bổ sung đầy đủ quyền <code>MemberRole.OWNER</code> ngang <code>MemberRole.MANAGER</code> trong <code>SectionPolicy</code> (<code>EDIT</code>, <code>RESTORE</code>, <code>SUBMIT</code> qua <code>coordinator</code>, <code>APPROVE</code>, <code>RETURN</code>, <code>REOPEN</code>).&lt;br/&gt;2. Kế thừa <code>task.getSupervisorId()</code> trong <code>SectionPolicy.supervisor()</code> &amp; <code>SectionNotifier.reviewers()</code>, đảm bảo <code>Task Supervisor</code> (kể cả <code>Creator</code> cấp cao <code>≠ assignee</code>) duyệt được các <code>Section</code> của Task.&lt;br/&gt;3. Cho phép <code>Owner</code>/<code>Manager</code> thực hiện <code>REOPEN</code> phần trên cả Task <code>IN_REVIEW</code> và <code>FINISHED</code> (khi bài đăng chưa <code>PUBLISHING</code>/<code>PUBLISHED</code>), gọi <code>settle(scope, false, note)</code> + <code>cancelSchedule(task)</code> giống <code>Client Return</code>.&lt;br/&gt;4. Tự động chuyển <code>TODO → IN_PROGRESS</code> khi <code>Section Owner</code> / <code>Coordinator</code> lưu nháp phần trên Task hợp lệ.&lt;br/&gt;5. Gọi <code>approvals.settleSections(scope, true, null)</code> ngay sau <strong>cả</strong> duyệt nội bộ (<code>APPROVE</code>) lẫn duyệt khách hàng (<code>CLIENT_APPROVE</code>) tại <code>SectionService.approve()</code>.</td></tr><tr><td style="text-align:left;"><strong>Backend — Task Approval &amp; Post Guard (<code>brandhub-business-service</code>)</strong></td><td style="text-align:left;"><code>service/impl/task/TaskApprovalPolicy.java</code>&lt;br/&gt;<code>service/impl/task/TaskApprovalService.java</code>&lt;br/&gt;<code>service/impl/task/TaskPostService.java</code>&lt;br/&gt;<code>service/impl/social/PostPublishServiceImpl.java</code></td><td style="text-align:left;">1. <code>TaskApprovalPolicy.agencyReviewer()</code>: cho phép <code>Owner</code>, mọi <code>Manager</code> active (khác <code>Creator</code> nộp) VÀ <code>task.supervisorId</code> (khác <code>assigneeId</code>) duyệt ở bước <code>MANAGER</code>.&lt;br/&gt;2. <code>TaskApprovalPolicy.skipsAgencyReview()</code>: chỉ trả <code>true</code> khi <code>assignee</code> có vai trò <code>Owner</code> hoặc <code>Manager</code> và <code>supervisorId.equals(assigneeId)</code>.&lt;br/&gt;3. <code>TaskApprovalService.selfApprove()</code>: chặn hoàn toàn khi <code>!isPersonal</code> (<code>403 TASK_SELF_APPROVE_NOT_ALLOWED</code>).&lt;br/&gt;4. Mở rộng <code>TaskApprovalService.settleSections()</code>: tự động chốt Task cha từ <code>IN_PROGRESS</code> → <code>FINISHED</code> (khi <code>!requiresClientApproval</code> &amp; đủ 100% phần), từ <code>IN_PROGRESS</code> → <code>IN_REVIEW (CLIENT)</code> (khi <code>requiresClientApproval</code> &amp; tất cả phần đạt tối thiểu <code>INTERNAL_APPROVED</code>), và từ <code>IN_PROGRESS</code> / <code>IN_REVIEW</code> → <code>FINISHED</code> (khi 100% phần đạt <code>finalState</code>).&lt;br/&gt;5. <code>TaskPostService</code>: hỗ trợ auto-start <code>TODO → IN_PROGRESS</code> khi người có quyền lưu bài nháp hợp lệ.&lt;br/&gt;6. <code>PostPublishServiceImpl.publishPost()</code>: kiểm tra người gọi phải là <code>Owner</code>, <code>Manager</code>, <code>Coordinator</code> (trên task đơn) hoặc chủ vai trò <code>POST_PUBLISHING</code> / <code>VIDEO_PUBLISH</code>.</td></tr><tr><td style="text-align:left;"><strong>Web Frontend — Task Detail, Board &amp; List (<code>brandhub-web</code>)</strong></td><td style="text-align:left;"><code>src/pages/tasks/components/TaskStatusControl.tsx</code>&lt;br/&gt;<code>src/pages/tasks/components/TaskWorkflowContent.tsx</code>&lt;br/&gt;<code>src/pages/tasks/components/views/hooks/useBoardDragAndDrop.ts</code>&lt;br/&gt;<code>src/pages/tasks/components/TaskBulkActionBar.tsx</code>&lt;br/&gt;<code>src/hooks/useTaskSections.ts</code>&lt;br/&gt;<code>src/components/task-sections/SectionReview.tsx</code></td><td style="text-align:left;">1. <code>TaskStatusControl.tsx</code>: render Badge trạng thái tĩnh (bỏ mũi tên <code>⌄</code> &amp; menu rỗng) khi <code>FINISHED</code> / <code>CANCELLED</code> hoặc <code>available.length === 0</code>; hiển thị nhãn phụ tiến độ phần (<code>X/Y phần đã duyệt</code> / bước chờ duyệt); mở rộng <code>reviewable</code> cho mọi <code>sourceType</code> (<code>MANUAL</code>, <code>CAMPAIGN_OUT_OF_SCOPE</code>, <code>CAMPAIGN</code>, <code>CONTENT_REQUEST</code>) và 8 <code>TaskType</code>.&lt;br/&gt;2. <code>TaskWorkflowContent.tsx</code>: sửa <code>canSelfApprove</code> chỉ bật khi <code>isPersonalMode === true</code>.&lt;br/&gt;3. <code>useBoardDragAndDrop.ts</code> &amp; <code>TaskBulkActionBar.tsx</code>: chặn kéo-thả / đổi hàng loạt sang <code>IN_REVIEW</code> và <code>FINISHED</code> (hiển thị toast hướng dẫn rõ ràng); ẩn <code>CANCELLED</code> đối với <code>Creator</code>.&lt;br/&gt;4. <code>useTaskSections.ts</code> &amp; <code>SectionReview.tsx</code>: kích hoạt callback <code>onUpdated()</code> và invalidate <code>[&quot;tasks&quot;]</code>, <code>[&quot;task-workflow&quot;]</code>, <code>[&quot;task-review&quot;]</code>, <code>[&quot;campaign-subtasks&quot;]</code> sau mọi thao tác Section để danh sách bên ngoài đồng bộ tức thì.</td></tr><tr><td style="text-align:left;"><strong>Web Frontend — Editor &amp; Approval Queue (<code>brandhub-web</code>)</strong></td><td style="text-align:left;"><code>src/pages/editor/index.tsx</code>&lt;br/&gt;<code>src/pages/task-approvals/hooks/useApprovalList.ts</code>&lt;br/&gt;<code>src/pages/task-approvals/components/ApprovalFilters.tsx</code></td><td style="text-align:left;">1. <code>editor/index.tsx</code>: cho phép cả <code>OWNER</code> và <code>MANAGER</code> chỉnh sửa nền tảng đích (<code>destinationsReadOnly = Boolean(taskId) &amp;&amp; !isPersonalMode &amp;&amp; role !== &quot;MANAGER&quot; &amp;&amp; role !== &quot;OWNER&quot;</code>).&lt;br/&gt;2. <code>useApprovalList.ts</code> &amp; <code>ApprovalFilters.tsx</code>: gỡ bỏ hardcode <code>type: &quot;POST&quot;</code>, hỗ trợ truy vấn và lọc đủ <strong>8 loại <code>TaskType</code></strong>.</td></tr><tr><td style="text-align:left;"><strong>Đa ngôn ngữ (i18n) &amp; Theme (<code>brandhub-web</code>)</strong></td><td style="text-align:left;"><code>src/i18n/locales/vi/tasks.json</code>&lt;br/&gt;<code>src/i18n/locales/en/tasks.json</code>&lt;br/&gt;<code>src/i18n/locales/vi/editor.json</code>&lt;br/&gt;<code>src/i18n/locales/en/editor.json</code></td><td style="text-align:left;">Bổ sung đồng bộ song song (<code>key-parallel</code>) các khóa dịch cho nhãn tiến độ trạng thái, thông báo chặn nhảy cóc Kanban/Bulk, bộ lọc loại công việc trên <code>/task-approvals</code> và thông báo lỗi phân quyền.</td></tr></tbody></table><hr><h2 id="_2-thiet-ke-chi-tiet-thuat-toan-tu-đong-chot-trang-thai-settlesections-v4-0" tabindex="-1">2. Thiết kế Chi tiết Thuật toán Tự động Chốt Trạng thái (<code>settleSections</code> v4.0) <a class="header-anchor" href="#_2-thiet-ke-chi-tiet-thuat-toan-tu-đong-chot-trang-thai-settlesections-v4-0" aria-label="Permalink to &quot;2. Thiết kế Chi tiết Thuật toán Tự động Chốt Trạng thái (`settleSections` v4.0)&quot;">​</a></h2><p>Không thay đổi schema vật lý của MongoDB hay PostgreSQL (giữ tương thích ngược 100% với toàn bộ dữ liệu hiện có). Thuật toán <code>TaskApprovalService.settleSections(Scope scope, boolean approved, String note)</code> được nâng cấp để xử lý nguyên tử trong Mongo Transaction:</p><ol><li><strong>Khi một phần bị trả lại hoặc mở lại (<code>approved == false</code>)</strong>: <ul><li>Nếu Task đang ở <code>FINISHED</code> (và <code>PostDocument</code> chưa <code>PUBLISHING</code>/<code>PUBLISHED</code>) hoặc đang ở <code>IN_REVIEW</code>: <ul><li>Ghi nhận sự kiện mở lại/từ chối vào <code>task_approvals</code> để bảo toàn bất biến <code>closedSubmission</code> của <code>TaskApprovalPolicy</code>.</li><li>Chuyển <code>task.status = &quot;IN_PROGRESS&quot;</code>, <code>task.reviewStep = null</code>, <code>task.finishedAt = null</code>, tăng <code>workflowRevision + 1</code>.</li><li>Chuyển <code>PostDocument</code> liên kết về <code>&quot;DRAFT&quot;</code> và hủy lịch hẹn giờ (<code>cancelSchedule</code>).</li></ul></li></ul></li><li><strong>Khi một phần được duyệt nội bộ hoặc duyệt bởi <code>Client</code> (<code>approved == true</code>)</strong>: <ul><li>Kiểm tra điều kiện tiên quyết của Task (<code>roleTask(task) == true</code>, không còn công việc con tự do mở <code>!hasOpenSubtasks</code>, và nếu là <code>POST</code>/<code>SHORT_VIDEO</code> thì <code>PostDocument</code> đã có <code>caption</code> không trống).</li><li>Tự động đóng nội bộ (<code>approveUnowned</code>) đối với các phần không có <code>Subtask</code> vai trò sở hữu riêng khi toàn bộ các phần có chủ sở hữu đã đạt <code>INTERNAL_APPROVED</code> / <code>CLIENT_APPROVED</code>.</li><li>Tính 2 cờ trạng thái tổng hợp trên toàn bộ <code>TaskCatalog.sectionsOf(task.getType())</code>: <ul><li><code>allInternallyApproved</code>: Mọi phần đều đạt <code>INTERNAL_APPROVED</code> hoặc <code>CLIENT_APPROVED</code>.</li><li><code>allFinal</code>: Mọi phần đều thỏa <code>SectionPolicy.isFinal(section, task.isRequiresClientApproval(), status)</code>.</li></ul></li><li><strong>Nhánh 1 (<code>allFinal == true</code> và <code>task.status</code> đang là <code>IN_PROGRESS</code> hoặc <code>IN_REVIEW</code>)</strong>: <ul><li>Chốt nguyên tử <code>task.status = &quot;FINISHED&quot;</code>, <code>task.reviewStep = null</code>, <code>task.finishedAt = now</code>, cập nhật <code>lastSubmission</code> với <code>outcome = &quot;APPROVED&quot;</code>, ghi bản ghi quyết định vào <code>task_approvals</code>, chuyển <code>PostDocument.status</code> sang <code>&quot;SCHEDULED&quot;</code> (nếu <code>publishDate != null</code>) hoặc <code>&quot;APPROVED&quot;</code>, và phát thông báo outbox.</li></ul></li><li><strong>Nhánh 2 (<code>allInternallyApproved == true &amp;&amp; !allFinal</code> — tức <code>requiresClientApproval == true</code> và còn phần <code>OUTPUT</code> đang chờ <code>Client</code>)</strong>: <ul><li>Nếu <code>task.status</code> đang là <code>&quot;IN_PROGRESS&quot;</code>, chuyển nguyên tử <code>task.status = &quot;IN_REVIEW&quot;</code>, <code>task.reviewStep = &quot;CLIENT&quot;</code>, cập nhật <code>lastSubmission</code> mở vòng hiện tại, và chuyển <code>PostDocument.status</code> sang <code>&quot;PENDING_APPROVAL&quot;</code>.</li></ul></li></ul></li></ol><hr><h2 id="_3-ke-hoach-đa-ngon-ngu-i18n-giao-dien-light-dark" tabindex="-1">3. Kế hoạch Đa ngôn ngữ (i18n) &amp; Giao diện Light/Dark <a class="header-anchor" href="#_3-ke-hoach-đa-ngon-ngu-i18n-giao-dien-light-dark" aria-label="Permalink to &quot;3. Kế hoạch Đa ngôn ngữ (i18n) &amp; Giao diện Light/Dark&quot;">​</a></h2>',12)),o("ul",null,[o("li",null,[e[9]||(e[9]=o("strong",null,[t("Các file i18n cập nhật đồng thời ("),o("code",null,"vi"),t(" ↔ "),o("code",null,"en"),t(")")],-1)),e[10]||(e[10]=t(": ",-1)),o("ul",null,[o("li",null,[e[4]||(e[4]=o("code",null,"brandhub-web/src/i18n/locales/vi/tasks.json",-1)),e[5]||(e[5]=t(" & ",-1)),e[6]||(e[6]=o("code",null,"brandhub-web/src/i18n/locales/en/tasks.json",-1)),e[7]||(e[7]=t(": ",-1)),o("ul",null,[o("li",null,[e[0]||(e[0]=o("code",null,"tasks.workflow.progressApproved",-1)),e[1]||(e[1]=t(": ",-1)),o("code",null,'"'+c("{{")+"done"+c("}}")+"/"+c("{{")+"total"+c("}}")+' phần đã duyệt"',1),e[2]||(e[2]=t(" / ",-1)),o("code",null,'"'+c("{{")+"done"+c("}}")+"/"+c("{{")+"total"+c("}}")+' sections approved"',1)]),e[3]||(e[3]=d("<li><code>tasks.workflow.waitingManager</code>: <code>&quot;Chờ Quản lý duyệt&quot;</code> / <code>&quot;Waiting for Manager&quot;</code></li><li><code>tasks.workflow.waitingClient</code>: <code>&quot;Chờ Khách hàng duyệt&quot;</code> / <code>&quot;Waiting for Client&quot;</code></li><li><code>tasks.workflow.approvedReady</code>: <code>&quot;Đã hoàn tất phê duyệt&quot;</code> / <code>&quot;Approval completed&quot;</code></li><li><code>tasks.board.cannotBypassApproval</code>: <code>&quot;Không thể chuyển thẳng sang trạng thái này. Vui lòng gửi duyệt và phê duyệt trong chi tiết công việc.&quot;</code> / <code>&quot;Cannot jump directly to this status. Please submit and approve via the task workflow.&quot;</code></li><li><code>tasks.approvalPage.allTypes</code>: <code>&quot;Tất cả loại công việc&quot;</code> / <code>&quot;All task types&quot;</code></li>",5))])]),e[8]||(e[8]=o("li",null,[o("code",null,"brandhub-web/src/i18n/locales/vi/editor.json"),t(" & "),o("code",null,"brandhub-web/src/i18n/locales/en/editor.json"),t(": đồng bộ thông báo khóa/mở lại phần.")],-1))])]),e[11]||(e[11]=d("<li><strong>Chuẩn Light / Dark Mode</strong>: <ul><li>Badge trạng thái tĩnh và nhãn phụ tiến độ trong <code>TaskStatusControl.tsx</code> sử dụng hệ màu semantic hiện có của <code>STATUS_CONFIG</code> (<code>emerald-500/10</code>, <code>amber-500/10</code>, <code>blue-500/10</code>, <code>border-border</code>, <code>text-muted-foreground</code> kèm <code>dark:text-*</code>), không dùng bất kỳ mã màu hex cứng nào.</li></ul></li>",1))]),e[13]||(e[13]=d('<hr><h2 id="_4-thu-tu-trien-khai-kiem-soat-rui-ro" tabindex="-1">4. Thứ tự Triển khai &amp; Kiểm soát Rủi ro <a class="header-anchor" href="#_4-thu-tu-trien-khai-kiem-soat-rui-ro" aria-label="Permalink to &quot;4. Thứ tự Triển khai &amp; Kiểm soát Rủi ro&quot;">​</a></h2><ol><li><strong>Bước 1 — Backend Policy &amp; Guards (<code>brandhub-business-service</code>)</strong>: Cập nhật <code>ErrorCode</code>, <code>SectionPolicy</code>, <code>TaskApprovalPolicy</code>, <code>TaskPlatformPolicy</code>, <code>TaskServiceImpl</code>, <code>TaskWorkflowService</code>, <code>CampaignSubtaskService</code>.</li><li><strong>Bước 2 — Backend Auto-Settlement &amp; Publish Guard (<code>brandhub-business-service</code>)</strong>: Cập nhật <code>SectionService</code>, <code>TaskApprovalService</code>, <code>TaskPostService</code>, <code>PostPublishServiceImpl</code> và viết/chạy bộ JUnit 5 kiểm chứng toàn bộ ma trận vai trò &amp; chuyển trạng thái.</li><li><strong>Bước 3 — Frontend Controls, Kanban/Bulk Guards, Approval Queue &amp; Cache Sync (<code>brandhub-web</code>)</strong>: Cập nhật <code>TaskStatusControl</code>, <code>TaskWorkflowContent</code>, <code>useBoardDragAndDrop</code>, <code>TaskBulkActionBar</code>, <code>useTaskSections</code>, <code>SectionReview</code>, <code>editor/index.tsx</code>, <code>useApprovalList</code>, <code>ApprovalFilters</code>.</li><li><strong>Bước 4 — Đồng bộ i18n (<code>vi</code>/<code>en</code>) &amp; Kiểm định Light/Dark + Build/Test</strong>: Cập nhật locale JSON song ngữ, chạy Vitest, <code>npx tsc -b</code>, <code>npx vite build</code> và kiểm tra trực quan.</li></ol>',3))])}const m=a(i,[["render",s]]);export{v as __pageData,m as default};
